    "door": "GET /api/v1/meta/flow/NAME/layers, plus the deprecated layers flag on the by-name door; every reading 200",
    "before_fix_base_e952cff578": {
      "unshipped_stored_row": {
        "before_hydration": "code null; no provenance flag; lock none, editable, deletable, not resettable",
        "after_hydration": "code = stored body; provenance flag org; lock none, editable, deletable, not resettable"
      },
      "stamped_unshipped": {
        "before_hydration": "code null; provenance flag package, package flag com.example.showcase (from the stored layer)",
        "after_hydration": "code = stored body; provenance flag org, package flag com.example.showcase (from the hydrated copy)"
      },
      "shipped_with_stored_row": {
        "before_hydration": "code = loader body; provenance package; resettable",
        "after_hydration": "code = loader body; provenance package; resettable"
      },
      "runtime_registered_no_package": {
        "before_hydration": "code = registered body; no stored layer",
        "after_hydration": "code = registered body; no stored layer"
      },
      "deprecated_layers_flag_unshipped": {
        "after_hydration": "code = stored body; provenance flag org"
      }
    },
    "after_fix_4a5639294d_and_merged_317eca662e": {
      "unshipped_stored_row": {
